**Problem Analysis:** Foreman Tick #82 – Host parameter inheritance broken when creating hosts via API with host group parameter overrides. When a host group defines default parameters, creating a host via the API with parameter overrides fails to merge correctly — the override is either silently dropped or raises a validation error.

**Root Cause:** The `HostParameterBuilder` in `app/services/host_parameter_builder.rb` incorrectly merges host group parameters with host-level overrides. The `merge_params!` method uses `Hash#merge` instead of a deep merge, causing nested parameter overrides to be lost. Additionally, the API controller's `create` action applies overrides before host group parameters are loaded, resulting in order-of-operations bugs.

**Fix:**

```ruby
# app/services/host_parameter_builder.rb
class HostParameterBuilder
  # Fix: Deep merge host group params with host-level overrides
  # preserving nested structures
  def merge_params!(host_group_params, host_params)
    # Before (broken):
    # host_group_params.merge(host_params)

    # After (fixed): deep merge with proper precedence
    deep_merge(host_group_params, host_params)
  end

  private

  def deep_merge(source, overrides)
    source.merge(overrides) do |_key, old_val, new_val|
      if old_val.is_a?(Hash) && new_val.is_a?(Hash)
        deep_merge(old_val, new_val)
      else
        new_val  # host-level overrides win for scalar values
      end
    end
  end
end
```

**API Controller Fix:**

```ruby
# app/controllers/api/v2/hosts_controller.rb
module Api
  module V2
    class HostsController < BaseController
      def create
        @host = Host.new(host_params)

        # Fix: Apply host group parameters FIRST, THEN merge overrides
        if params[:host][:hostgroup_id].present?
          host_group = Hostgroup.find(params[:host][:hostgroup_id])
          @host.apply_hostgroup_parameters(host_group)
        end

        # Now apply user-specified parameter overrides (these win)
        if params[:host][:host_parameters_attributes].present?
          @host.parameters_attributes = params[:host][:host_parameters_attributes]
        end

        # Now merge everything correctly
        HostParameterBuilder.new.merge_params!(
          @host.hostgroup_params,
          @host.host_params
        )

        if @host.save
          render json: @host, status: :created
        else
          render json: { errors: @host.errors.full_messages }, status: :unprocessable_entity
        end
      end
    end
  end
end
```

**E2E Test (TypeScript using Playwright + API):**

```typescript
// test/e2e/host-parameter-override.spec.ts
import { test, expect } from '@playwright/test';
import axios, { AxiosInstance } from 'axios';

const FOREMAN_URL = process.env.FOREMAN_URL || 'https://foreman.example.com';
const API_USER = process.env.FOREMAN_USER || 'admin';
const API_PASS = process.env.FOREMAN_PASS || 'changeme';

interface ForemanApi extends AxiosInstance {}

function createApi(): ForemanApi {
  const api = axios.create({
    baseURL: `${FOREMAN_URL}/api/v2`,
    auth: { username: API_USER, password: API_PASS },
    headers: { 'Content-Type': 'application/json' },
  });
  return api;
}

test.describe('Foreman Tick #82 - Host parameter override E2E', () => {
  let api: ForemanApi;
  let orgId: number;
  let locId: number;
  let hostgroupId: number;
  let hostId: number;
  let domainId: number;
  let subnetId: number;

  test.beforeAll(async () => {
    api = createApi();

    // 1. Create test organization
    const orgRes = await api.post('/organizations', {
      name: `tick82-org-${Date.now()}`
    });
    orgId = orgRes.data.id;

    // 2. Create test location
    const locRes = await api.post('/locations', {
      name: `tick82-loc-${Date.now()}`
    });
    locId = locRes.data.id;

    // 3. Create domain
    const domRes = await api.post('/domains', {
      name: 'tick82.example.com',
      organization_ids: [orgId],
      location_ids: [locId],
    });
    domainId = domRes.data.id;

    // 4. Create subnet
    const subRes = await api.post('/subnets', {
      name: 'tick82-subnet',
      network: '10.0.82.0',
      mask: '255.255.255.0',
      organization_ids: [orgId],
      location_ids: [locId],
    });
    subnetId = subRes.data.id;

    // 5. Create host group WITH default parameters
    const hgRes = await api.post('/hostgroups', {
      name: `tick82-hg-${Date.now()}`,
      organization_ids: [orgId],
      location_ids: [locId],
      host_parameters_attributes: [
        { name: 'env', value: 'staging' },
        { name: 'monitoring_enabled', value: 'true' },
        { name: 'nested_config', value: JSON.stringify({
          log_level: 'info',
          retry_count: 3,
          timeout: 30
        })},
      ]
    });
    hostgroupId = hgRes.data.id;
  });

  test('TC-01: Create host with parameter override - scalar override', async () => {
    // Override 'env' from 'staging' -> 'production'
    const res = await api.post('/hosts', {
      name: `web-${Date.now()}`,
      hostgroup_id: hostgroupId,
      domain_id: domainId,
      subnet_id: subnetId,
      organization_id: orgId,
      location_id: locId,
      host_parameters_attributes: [
        { name: 'env', value: 'production' }
      ]
    });

    expect(res.status).toBe(201);
    hostId = res.data.id;

    // Verify parameter was overridden, not just appended
    const hostParams = res.data.host_parameters || res.data.parameters;
    const envParam = hostParams.find((p: any) => p.name === 'env');
    expect(envParam).toBeDefined();
    expect(envParam.value).toBe('production');

    // Verify inherited parameters are preserved
    const monitoringParam = hostParams.find((p: any) => p.name === 'monitoring_enabled');
    expect(monitoringParam).toBeDefined();
    expect(monitoringParam.value).toBe('true');
  });

  test('TC-02: Create host with nested parameter override', async () => {
    // Override nested config: change timeout from 30 -> 60
    const res = await api.post('/hosts', {
      name: `web-nested-${Date.now()}`,
      hostgroup_id: hostgroupId,
      domain_id: domainId,
      subnet_id: subnetId,
      organization_id: orgId,
      location_id: locId,
      host_parameters_attributes: [
        { 
          name: 'nested_config', 
          value: JSON.stringify({
            log_level: 'debug',
            retry_count: 3,
            timeout: 60
          })
        }
      ]
    });

    expect(res.status).toBe(201);
    const hostParams = res.data.host_parameters || res.data.parameters;

    // Deep merge should preserve retry_count from host group
    // while overriding log_level and timeout
    const nestedParam = hostParams.find((p: any) => p.name === 'nested_config');
    expect(nestedParam).toBeDefined();

    const parsed = JSON.parse(nestedParam.value);
    expect(parsed.log_level).toBe('debug');   // overridden
    expect(parsed.timeout).toBe(60);           // overridden
    expect(parsed.retry_count).toBe(3);        // preserved from host group
  });

  test('TC-03: Create host without overrides - inherits all host group params', async () => {
    const res = await api.post('/hosts', {
      name: `web-no-override-${Date.now()}`,
      hostgroup_id: hostgroupId,
      domain_id: domainId,
      subnet_id: subnetId,
      organization_id: orgId,
      location_id: locId,
    });

    expect(res.status).toBe(201);
    const hostParams = res.data.host_parameters || res.data.parameters;
    const envParam = hostParams.find((p: any) => p.name === 'env');
    expect(envParam.value).toBe('staging');  // inherited unchanged
  });

  test('TC-04: Error case - invalid parameter type raises validation', async () => {
    const res = await api.post('/hosts', {
      name: `web-invalid-${Date.now()}`,
      hostgroup_id: hostgroupId,
      domain_id: domainId,
      subnet_id: subnetId,
      organization_id: orgId,
      location_id: locId,
      host_parameters_attributes: [
        { name: 'env', value: '' }  // empty value should fail if required
      ]
    });

    // Depending on parameter validation rules, this may be accepted or rejected
    // If 'env' is required, expect validation error
    expect(res.status === 201 || res.status === 422).toBe(true);
    if (res.status === 422) {
      expect(res.data.error).toBeDefined();
      expect(res.data.errors).toBeDefined();
    }
  });

  test.afterAll(async () => {
    // Cleanup
    if (hostId) await api.delete(`/hosts/${hostId}`).catch(() => {});
    if (hostgroupId) await api.delete(`/hostgroups/${hostgroupId}`).catch(() => {});
    if (subnetId) await api.delete(`/subnets/${subnetId}`).catch(() => {});
    if (domainId) await api.delete(`/domains/${domainId}`).catch(() => {});
    if (locId) await api.delete(`/locations/${locId}`).catch(() => {});
    if (orgId) await api.delete(`/organizations/${orgId}`).catch(() => {});
  });
});
